// PORT: the `#[derive(Diagnostic)]` structs of this file (`RequireTransparent`, `RequireOneField`,
// `RequireOneGeneric`, `RequireOnePointee`, `TooManyPointees`, `RequiresMaybeSized`) are generated by
// tools/codegen into coerce_pointee.gen.ts; the visitor structs (`TypeSubstitution`,
// `DetectNonGenericPointeeAttr`, `AlwaysErrorOnGenericParam`) are classes here.
import { mut_visit, visit } from "../../rustc_ast/lib.ts";
import { DUMMY_NODE_ID } from "../../rustc_ast/node_id.ts";
import type { ExtCtxt } from "../../rustc_expand/base.ts";
import type { Span } from "../../rustc_span/lib.ts";
import { Ident, type Symbol, sym } from "../../rustc_span/symbol.ts";
import * as diagnostics from "../diagnostics.ts";
import {
  RequireOneField_diagnostic,
  RequireOneGeneric_diagnostic,
  RequireOnePointee_diagnostic,
  RequiresMaybeSized_diagnostic,
  RequireTransparent_diagnostic,
  TooManyPointees_diagnostic,
} from "./coerce_pointee.gen.ts";
import { ast, generic_param_to_arg, generics_without_defaults } from "./generic/mod.ts";
import { new_path, path_std } from "./mod.ts";

export * from "./coerce_pointee.gen.ts";

// rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:19 expand_deriving_coerce_pointee
export function expand_deriving_coerce_pointee(
  cx: ExtCtxt,
  span: Span,
  item: ast.Item,
  push: (item: ast.Item) => void,
  _is_const: boolean,
): void {
  new DetectNonGenericPointeeAttr(cx).visit_item(item);

  let name_ident: Ident;
  let generics: ast.Generics;
  if (item.kind.$ === "Struct") {
    const [ident, g, struct_data] = [item.kind._0, item.kind._1, item.kind._2];
    if (
      !(
        (struct_data.$ === "Struct" && struct_data.fields.length !== 0) ||
        (struct_data.$ === "Tuple" && struct_data._0.length !== 0)
      )
    ) {
      cx.dcx().emit_err(RequireOneField_diagnostic({ span }));
      return;
    }
    [name_ident, generics] = [ident, g];
  } else {
    cx.dcx().emit_err(RequireTransparent_diagnostic({ span }));
    return;
  }

  // Convert generic parameters (from the struct) into generic args.
  const self_params: ast.GenericArg[] = generics.params.map((p) => generic_param_to_arg(cx, p, p.span()));
  const type_params: [number, Span, boolean][] = generics.params.flatMap((p, idx): [number, Span, boolean][] => {
    if (p.kind.$ === "Type") {
      return [[idx, p.span(), p.attrs.some((attr) => attr.has_name(sym.pointee))]];
    } else {
      return [];
    }
  });

  let pointee_param_idx: number;
  if (type_params.length === 0) {
    // `#[derive(CoercePointee)]` requires at least one generic type on the target `struct`
    cx.dcx().emit_err(RequireOneGeneric_diagnostic({ span }));
    return;
  } else if (type_params.length === 1) {
    // Regardless of the only type param being designed as `#[pointee]` or not, we can just use it as such
    pointee_param_idx = type_params[0]![0];
  } else {
    const pointees = type_params.flatMap(([idx, span, is_pointee]): [number, Span][] => (is_pointee ? [[idx, span]] : []));
    const [p0, p1] = [pointees[0], pointees[1]];
    if (p0 !== undefined && p1 === undefined) {
      const [idx, _span] = p0;
      pointee_param_idx = idx;
    } else if (p0 === undefined) {
      cx.dcx().emit_err(RequireOnePointee_diagnostic({ span }));
      return;
    } else {
      const [[, one], [, another]] = [p0, p1!];
      cx.dcx().emit_err(TooManyPointees_diagnostic({ one, another }));
      return;
    }
  }

  // Create the type of `self`.
  const path = cx.path_all(span, false, [name_ident], self_params.map(ast.clone_GenericArg));
  const self_type = cx.ty_path(path);

  // Declare helper function that adds implementation blocks.
  // FIXME(dingxiangfei2009): Investigate the set of attributes on target struct to be propagated to impls
  const attrs: ast.AttrVec = [cx.attr_word(sym.automatically_derived, span)];
  // # Validity assertion which will be checked later in `rustc_hir_analysis::coherence::builtins`.
  {
    const trait_path = path_std(cx, span, [sym.marker, sym.CoercePointeeValidated]);
    push(
      cx.item_trait_impl(
        span,
        attrs.map(ast.clone_Attribute),
        generics_without_defaults(generics),
        ast.Safety.Default,
        false,
        cx.trait_ref(trait_path),
        ast.clone_Ty(self_type),
        [],
      ),
    );
  }
  const add_impl_block = (generics: ast.Generics, trait_symbol: Symbol, trait_args: ast.Ty[]): void => {
    const trait_path = new_path(cx, span, [sym.ops, trait_symbol], trait_args);
    const trait_ref = cx.trait_ref(trait_path);
    const item = cx.item_trait_impl(span, attrs.map(ast.clone_Attribute), generics, ast.Safety.Default, false, trait_ref, ast.clone_Ty(self_type), []);
    push(item);
  };

  // Create unsized `self`, that is, one where the `#[pointee]` type arg is replaced with `__S`. For
  // example, instead of `MyType<'a, T>`, it will be `MyType<'a, __S>`.
  const s_ty = cx.ty_ident(span, Ident.new(sym.__S, span));
  const alt_self_params = self_params;
  alt_self_params[pointee_param_idx] = { $: "Type", _0: ast.clone_Ty(s_ty) };
  const alt_self_type = cx.ty_path(cx.path_all(span, false, [name_ident], alt_self_params));

  // # Add `Unsize<__S>` bound to `#[pointee]` at the generic parameter location
  //
  // Find the `#[pointee]` parameter and add an `Unsize<__S>` bound to it.
  const impl_generics = ast.clone_Generics(generics);
  const pointee_ty_ident = generics.params[pointee_param_idx]!.ident;
  let self_bounds: ast.GenericBounds;
  {
    const pointee = impl_generics.params[pointee_param_idx]!;
    self_bounds = pointee.bounds.map(ast.clone_GenericBound);
    if (!contains_maybe_sized_bound(self_bounds) && !contains_maybe_sized_bound_on_pointee(generics.where_clause.predicates, pointee_ty_ident.name)) {
      cx.dcx().emit_err(
        RequiresMaybeSized_diagnostic({
          span: pointee_ty_ident.span,
          name: pointee_ty_ident,
        }),
      );
      return;
    }
    const arg: ast.GenericArg = { $: "Type", _0: ast.clone_Ty(s_ty) };
    const unsize = cx.path_all(span, true, cx.std_path([sym.marker, sym.Unsize]), [arg]);
    pointee.bounds.push(cx.trait_bound(unsize, false));
    // Drop `#[pointee]` attribute since it should not be recognized outside `derive(CoercePointee)`
    pointee.attrs = pointee.attrs.filter((attr) => !attr.has_name(sym.pointee));
  }

  // # Rewrite generic parameter bounds
  // For each bound `U: ..` in `struct<U: ..>`, make a new bound with `__S` in place of `#[pointee]`
  // Example:
  // ```
  // struct<
  //     U: Trait<T>,
  //     #[pointee] T: Trait<T> + ?Sized,
  //     V: Trait<T>> ...
  // ```
  // ... generates this `impl` generic parameters
  // ```
  // impl<
  //     U: Trait<T> + Trait<__S>,
  //     T: Trait<T> + ?Sized + Unsize<__S>, // (**)
  //     __S: Trait<__S> + ?Sized, // (*)
  //     V: Trait<T> + Trait<__S>> ...
  // ```
  // The new bound marked with (*) has to be done separately.
  // See next section
  const n = Math.min(impl_generics.params.length, generics.params.length);
  for (let idx = 0; idx < n; idx++) {
    const params = impl_generics.params[idx]!;
    const orig_params = generics.params[idx]!;
    // Default type parameters are rejected for `impl` block.
    // We should drop them now.
    const kind = params.kind;
    switch (kind.$) {
      case "Const":
        kind.default = undefined;
        break;
      case "Type":
        kind.default = undefined;
        break;
      case "Lifetime":
        break;
    }
    // We CANNOT rewrite `#[pointee]` type parameter bounds.
    // This has been set in stone. (**)
    // So we skip over it.
    // Otherwise, we push extra bounds involving `__S`.
    if (idx !== pointee_param_idx) {
      for (const bound_ of orig_params.bounds) {
        const bound = ast.clone_GenericBound(bound_);
        const substitution = new TypeSubstitution(pointee_ty_ident.name, s_ty, false);
        substitution.visit_param_bound(bound, "Bound");
        if (substitution.rewritten) {
          // We found use of `#[pointee]` somewhere,
          // so we make a new bound using `__S` in place of `#[pointee]`
          params.bounds.push(bound);
        }
      }
    }
  }

  // # Insert `__S` type parameter
  //
  // We now insert `__S` with the missing bounds marked with (*) above.
  // We should also write the bounds from `#[pointee]` to `__S` as required by `Unsize<__S>`.
  {
    const substitution = new TypeSubstitution(pointee_ty_ident.name, s_ty, false);
    for (const bound of self_bounds) {
      substitution.visit_param_bound(bound, "Bound");
    }
  }

  // # Rewrite `where` clauses
  //
  // Move on to `where` clauses.
  // Example:
  // ```
  // struct MyPointer<#[pointee] T, ..>
  // where
  //   U: Trait<V> + Trait<T>,
  //   Companion<T>: Trait<T>,
  //   T: Trait<T> + ?Sized,
  // { .. }
  // ```
  // ... will have a impl prelude like so
  // ```
  // impl<..> ..
  // where
  //   U: Trait<V> + Trait<T>,
  //   U: Trait<__S>,
  //   Companion<T>: Trait<T>,
  //   Companion<__S>: Trait<__S>,
  //   T: Trait<T> + ?Sized,
  //   __S: Trait<__S> + ?Sized,
  // ```
  //
  // We should also write a few new `where` bounds from `#[pointee] T` to `__S`
  // as well as any bound that indirectly involves the `#[pointee] T` type.
  for (const predicate of generics.where_clause.predicates) {
    if (predicate.kind.$ === "BoundPredicate") {
      const bound = predicate.kind._0;
      const substitution = new TypeSubstitution(pointee_ty_ident.name, s_ty, false);
      const kind: ast.WherePredicateKind = { $: "BoundPredicate", _0: ast.clone_WhereBoundPredicate(bound) };
      substitution.visit_where_predicate_kind(kind);
      if (substitution.rewritten) {
        const predicate_: ast.WherePredicate = {
          attrs: predicate.attrs.map(ast.clone_Attribute),
          kind,
          span: predicate.span,
          id: DUMMY_NODE_ID,
          is_placeholder: false,
        };
        impl_generics.where_clause.predicates.push(predicate_);
      }
    }
  }

  const extra_param = cx.typaram(Ident.new(sym.__S, span), self_bounds, undefined);
  impl_generics.params.splice(pointee_param_idx + 1, 0, extra_param);

  // Add the impl blocks for `DispatchFromDyn` and `CoerceUnsized`.
  const gen_args = [alt_self_type];
  add_impl_block(ast.clone_Generics(impl_generics), sym.DispatchFromDyn, gen_args.map(ast.clone_Ty));
  add_impl_block(impl_generics, sym.CoerceUnsized, gen_args);
}

// rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:275 contains_maybe_sized_bound_on_pointee
function contains_maybe_sized_bound_on_pointee(predicates: readonly ast.WherePredicate[], pointee: Symbol): boolean {
  for (const bound of predicates) {
    if (bound.kind.$ === "BoundPredicate") {
      const bound_ = bound.kind._0;
      const name = ast.TyKind.is_simple_path(bound_.bounded_ty.kind);
      if (name !== undefined && name === pointee) {
        if (contains_maybe_sized_bound(bound_.bounds)) {
          return true;
        }
      }
    }
  }
  return false;
}

// rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:288 is_maybe_sized_bound
function is_maybe_sized_bound(bound: ast.GenericBound): boolean {
  if (bound.$ === "Trait" && bound._0.modifiers.polarity.$ === "Maybe" && is_sized_marker(bound._0.trait_ref.path)) {
    return true;
  } else {
    return false;
  }
}

// rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:300 contains_maybe_sized_bound
function contains_maybe_sized_bound(bounds: readonly ast.GenericBound[]): boolean {
  return bounds.some(is_maybe_sized_bound);
}

// rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:304 is_sized_marker
function is_sized_marker(path: ast.Path): boolean {
  const CORE_UNSIZE: readonly Symbol[] = [sym.core, sym.marker, sym.Sized];
  const STD_UNSIZE: readonly Symbol[] = [sym.std, sym.marker, sym.Sized];
  const segments = (): Symbol[] => path.segments.map((segment) => segment.ident.name);
  const eq = (a: readonly Symbol[], b: readonly Symbol[]): boolean => a.length === b.length && a.every((s, i) => s === b[i]);
  if (path.is_global()) {
    return eq(segments().slice(1), CORE_UNSIZE) || eq(segments().slice(1), STD_UNSIZE);
  } else {
    return eq(segments(), CORE_UNSIZE) || eq(segments(), STD_UNSIZE) || path.eq_Symbol(sym.Sized);
  }
}

class TypeSubstitution extends mut_visit.MutVisitor {
  constructor(
    public from_name: Symbol,
    public to_ty: ast.Ty,
    public rewritten: boolean,
  ) {
    super();
  }

  // rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:322 visit_ty
  override visit_ty(ty: ast.Ty): void {
    const name = ast.TyKind.is_simple_path(ty.kind);
    if (name !== undefined && name === this.from_name) {
      // PORT: `*ty = self.to_ty.clone()` -> replaced in place (see the note in rustc_ast/mut_visit.ts).
      Object.assign(ty, ast.clone_Ty(this.to_ty));
      this.rewritten = true;
    } else {
      mut_visit.walk_ty(this, ty);
    }
  }

  // rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:333 visit_where_predicate_kind
  override visit_where_predicate_kind(kind: ast.WherePredicateKind): void {
    switch (kind.$) {
      case "BoundPredicate": {
        const bound = kind._0;
        // PORT: `flat_map_in_place` on the `ThinVec` -> the mapped elements written back in place.
        const params = bound.bound_generic_params.flatMap((param) => this.flat_map_generic_param(param));
        bound.bound_generic_params.length = 0;
        bound.bound_generic_params.push(...params);
        this.visit_ty(bound.bounded_ty);
        for (const bound_ of bound.bounds) {
          this.visit_param_bound(bound_, "Bound");
        }
        break;
      }
      case "RegionPredicate":
        break;
    }
  }
}

class DetectNonGenericPointeeAttr extends visit.Visitor {
  constructor(public cx: ExtCtxt) {
    super();
  }

  // rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:354 visit_attribute
  override visit_attribute(attr: ast.Attribute): undefined {
    if (attr.has_name(sym.pointee)) {
      this.cx.dcx().emit_err(diagnostics.NonGenericPointee_diagnostic({ span: attr.span }));
    }
    return undefined;
  }

  // rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:360 visit_generic_param
  override visit_generic_param(param: ast.GenericParam): undefined {
    const error_on_pointee = new AlwaysErrorOnGenericParam(this.cx);

    switch (param.kind.$) {
      case "Type": {
        const default_ = param.kind.default;
        // The `default` may end up containing a block expression.
        // The problem is block expressions  may define structs with generics.
        // A user may attach a #[pointee] attribute to one of these generics
        // We want to catch that. The simple solution is to just
        // always raise a `NonGenericPointee` error when this happens.
        //
        // This solution does reject valid rust programs but,
        // such a code would have to, in order:
        // - Define a smart pointer struct.
        // - Somewhere in this struct definition use a type with a const generic argument.
        // - Calculate this const generic in a expression block.
        // - Define a new smart pointer type in this block.
        // - Have this smart pointer type have more than 1 generic type.
        // In this case, the inner smart pointer derive would be complaining that it
        // needs a pointer attribute. Meanwhile, the outer macro would be complaining
        // that we attached a #[pointee] to a generic type argument while helpfully
        // informing the user that #[pointee] can only be attached to generic pointer arguments
        if (default_ !== undefined) error_on_pointee.visit_ty(default_);
        break;
      }

      case "Const":
      case "Lifetime": {
        visit.walk_generic_param(error_on_pointee, param);
        break;
      }
    }
    return undefined;
  }

  // rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:391 visit_ty
  override visit_ty(t: ast.Ty): undefined {
    const error_on_pointee = new AlwaysErrorOnGenericParam(this.cx);
    return error_on_pointee.visit_ty(t);
  }
}

class AlwaysErrorOnGenericParam extends visit.Visitor {
  constructor(public cx: ExtCtxt) {
    super();
  }

  // rustc: compiler/rustc_builtin_macros/src/deriving/coerce_pointee.rs:402 visit_attribute
  override visit_attribute(attr: ast.Attribute): undefined {
    if (attr.has_name(sym.pointee)) {
      this.cx.dcx().emit_err(diagnostics.NonGenericPointee_diagnostic({ span: attr.span }));
    }
    return undefined;
  }
}
